var s=UnityEngine.Object.FindFirstObjectByType<ChooGuard.App.Mvp.MvpStationView>(); var renderers=s.GetComponentsInChildren<UnityEngine.Renderer>(true); var meshes=s.GetComponentsInChildren<UnityEngine.MeshFilter>(true); var hubs=s.GetComponentsInChildren<ChooGuard.App.Mvp.MvpInteriorHubView>(true); long triangles=0; foreach(var m in meshes) if(m.sharedMesh!=null) triangles+=m.sharedMesh.triangles.Length/3; int badMaterials=0; foreach(var r in renderers) foreach(var m in r.sharedMaterials) if(m==null||m.shader==null||m.shader.name=="Hidden/InternalErrorShader")badMaterials++; return new { scene=s.gameObject.scene.path,dirty=s.gameObject.scene.isDirty,renderers=renderers.Length,meshObjects=meshes.Length,triangles=triangles,badMaterials=badMaterials,hubs=System.Array.ConvertAll(hubs,h=>new{sourceId=h.SourceId,shell=h.ShellRenderers.Length,interior=h.InteriorRenderers.Length}),floors=System.Array.ConvertAll(s.FloorRoots,f=>new{name=f.name,renderers=f.GetComponentsInChildren<UnityEngine.Renderer>(true).Length}) };